import { MANIFEST } from '@/content/site'

// Web app manifest (/manifest.webmanifest). Icons are generated by `npm run assets`.
export default function manifest() {
  const icons = [192, 512].map((size) => ({
    src: `/icons/icon-${size}.png`,
    sizes: `${size}x${size}`,
    type: 'image/png',
  }))
  return {
    name: MANIFEST.name,
    short_name: MANIFEST.shortName,
    description: MANIFEST.description,
    start_url: '/',
    display: 'standalone',
    background_color: MANIFEST.color,
    theme_color: MANIFEST.color,
    icons: [
      ...icons.map((icon) => ({ ...icon, purpose: 'any' })),
      ...icons.map((icon) => ({ ...icon, purpose: 'maskable' })),
    ],
  }
}
